	@Test
	@Timeout(value = 60, threadMode = Timeout.ThreadMode.SEPARATE_THREAD)
	void savingAndRestartingARepositoryDoesNotDeadlockWithARemoval(@TempDir File directory) throws Exception {
		CountDownLatch shuttingDown = new CountDownLatch(1);
		CountDownLatch resume = new CountDownLatch(1);
		LocalRepositoryManager manager = managerWithFirstShutdown(directory, () -> {
			shuttingDown.countDown();
			try {
				resume.await();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
		});
		manager.init();
		ExecutorService threads = Executors.newFixedThreadPool(2);
		Future<?> update = null;
		Future<Boolean> removal = null;
		try {
			manager.addRepositoryConfig(sparqlConfig("edited"));
			manager.addRepositoryConfig(sparqlConfig("removed"));
			manager.getRepository("edited");
			// The update holds the cached repositories while it shuts the edited one down...
			update = threads.submit(() -> manager.updateRepositoryConfig(sparqlConfig("edited")));
			assertThat(shuttingDown.await(10, TimeUnit.SECONDS)).isTrue();
			// ...when another request removes a repository; the update then reads the saved configuration again.
			AtomicReference<Thread> remover = new AtomicReference<>();
			removal = threads.submit(() -> {
				remover.set(Thread.currentThread());
				return manager.removeRepository("removed");
			});
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
			while (remover.get() == null || remover.get().getState() != Thread.State.BLOCKED) {
				assertThat(System.nanoTime()).as("the removal waits for the update").isLessThan(deadline);
				Thread.onSpinWait();
			}
			resume.countDown();

			update.get(10, TimeUnit.SECONDS);
			assertThat(removal.get(10, TimeUnit.SECONDS)).isTrue();
		} finally {
			resume.countDown();
			threads.shutdownNow();
			if (update != null && update.isDone() && removal != null && removal.isDone()) {
				manager.shutDown();
			}
		}
	}

	@Test
	void aRepositoryThatFailsToShutDownIsNotKeptAfterItsConfigurationWasReplaced(@TempDir File directory) {
		LocalRepositoryManager manager = managerWithFirstShutdown(directory, () -> {
			throw new RepositoryException("the store is locked");
		});
		manager.init();
		try {
			manager.addRepositoryConfig(sparqlConfig("edited"));
			Repository previous = manager.getRepository("edited");

			assertThatThrownBy(() -> manager.updateRepositoryConfig(sparqlConfig("edited")))
					.isInstanceOf(RepositoryException.class)
					.hasMessageContaining("could not shut down");
			assertThat(manager.getRepository("edited")).isNotSameAs(previous);
		} finally {
			manager.shutDown();
		}
	}

	/** A manager whose first instance of repository "edited" runs {@code firstShutdown} when it is shut down. */
	private static LocalRepositoryManager managerWithFirstShutdown(File directory, Runnable firstShutdown) {
		AtomicBoolean first = new AtomicBoolean(true);
		return new LocalRepositoryManager(directory) {
			@Override
			protected Repository createRepository(String id) {
				Repository created = super.createRepository(id);
				if (created == null || !"edited".equals(id)) {
					return created;
				}
				return new RepositoryWrapper(created) {
					@Override
					public void shutDown() {
						if (first.getAndSet(false)) {
							firstShutdown.run();
						}
						super.shutDown();
					}
				};
			}
		};
	}

	private static RepositoryConfig sparqlConfig(String id) {
		return new RepositoryConfig(id, new SPARQLRepositoryConfig("https://example.org/sparql"));
	}

	private Path createRepositorySymlink() throws IOException {
		Path repositories = Files.createDirectories(dataDir.toPath().resolve(LocalRepositoryManager.REPOSITORIES_DIR));
		Path outside = Files.createDirectories(dataDir.toPath().resolve("outside"));
		Files.createSymbolicLink(repositories.resolve("linked"), outside);
		return outside;
	}

